const estadoFacturaCalc = (factura) => {
  const total = parseFloat(factura.total) || 0;
  const pagado = (factura.pagos || []).reduce((s, p) => s + (parseFloat(p.importe) || 0), 0);
  if (pagado <= 0) return "Pendiente";
  if (pagado < total) return "Parcial";
  return "Pagada";
};

